const WEEKS = 12;
const MIN_LEN = 40;
const MAX_LEN = 280;
const MAX_REVIEWS = 400;
const cutoff = Date.now() - WEEKS * 7 * 864e5;
const pick = (r, names) => {
  const k = Object.keys(r).find(k => names.includes(k.toLowerCase()));
  return k ? r[k] : undefined;
};

const seen = new Set();
let pool = [];
let raw = 0;
for (const item of $input.all()) {
  raw++;
  const r = item.json;
  const text = String(pick(r, ['content', 'review', 'text']) || '').trim();
  if (text.length < MIN_LEN || text.length > MAX_LEN) continue;
  const key = text.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  const d = pick(r, ['at', 'date']);
  const t = d ? Date.parse(d) : NaN;
  if (!isNaN(t) && t < cutoff) continue;
  const s = Number(pick(r, ['score', 'rating']));
  pool.push({ text, score: isNaN(s) ? null : s, date: d || null });
}

if (pool.length < 10) {
  throw new Error('Only ' + pool.length + ' usable reviews. Check column names and dates.');
}

// Spread the sample evenly across the 12 weeks instead of taking the newest rows
pool.sort((a, b) => (Date.parse(a.date) || 0) - (Date.parse(b.date) || 0));
const step = Math.max(1, pool.length / MAX_REVIEWS);
const reviews = [];
for (let i = 0; i < MAX_REVIEWS && Math.floor(i * step) < pool.length; i++) {
  const r = pool[Math.floor(i * step)];
  reviews.push({ id: reviews.length, text: r.text, score: r.score, date: r.date });
}

const reviewsText = reviews.map(r => `[${r.id}] (${r.score}*) ${r.text}`).join('\n');

return [{ json: { reviews, reviewsText, count: reviews.length, poolSize: pool.length, rawRows: raw, weeks: WEEKS } }];

