const prep = $('Prepare Reviews').first().json;
const agent = $('AI Agent').first().json.output;
const reviews = prep.reviews;
const N = reviews.length;
const byId = Object.fromEntries(reviews.map(r => [r.id, r]));
const pretty = s => { const t = String(s).replace(/_/g, ' ').trim(); return t.charAt(0).toUpperCase() + t.slice(1); };

// 1. Themes: the agent named them, the labels from Classify Reviews place each review
const themes = (agent.themes || []).slice(0, 5).map(t => ({ name: pretty(t.name), ids: [] }));
const labelled = new Set();
for (const item of $input.all()) {
  const j = item.json;
  const raw = typeof j.text === 'string' ? j.text : (typeof j.output === 'string' ? j.output : JSON.stringify(j));
  for (const m of raw.matchAll(/(\d+)\s*,\s*(\d+)/g)) {
    const id = Number(m[1]), th = Number(m[2]);
    if (!byId[id] || labelled.has(id)) continue;
    labelled.add(id);
    if (th >= 1 && th <= themes.length) themes[th - 1].ids.push(id);
  }
}
if (labelled.size < 0.9 * N) throw new Error('The model labelled only ' + labelled.size + ' of ' + N + ' reviews. Run again.');
const ranked = themes.filter(t => t.ids.length > 0).sort((a, b) => b.ids.length - a.ids.length);
if (ranked.length < 3) throw new Error('Fewer than 3 themes have labelled reviews.');
const top = ranked.slice(0, 3);

// 2. Quotes: one per top theme, word for word from the sheet, complaints first
const BAD = /\b(fuck|shit|bsdk|chutiya|chor|gadhe|bakwas|ghatiya|rubbish|pathetic|fraud|scam|scammers?|loot|cheaters?|idiot|bhogash|looters?)\b/i;
const nonAscii = s => (s.match(/[^\x00-\x7F]/g) || []).length / s.length;
const used = new Set();
const quotes = top.map(t => {
  const cands = t.ids.map(i => byId[i])
    .filter(r => r.text.length >= 40 && r.text.length <= 160 && nonAscii(r.text) < 0.01 && (r.text.toLowerCase().match(/\b(the|and|is|are|not|my|this|for|with|have|was|that|they|you|your|but)\b/g) || []).length >= 3 && !BAD.test(r.text) && !/uninstall|download|install|worst/i.test(r.text) && !used.has(r.id))
    .sort((a, b) => ((a.score || 3) > 3) - ((b.score || 3) > 3) || b.text.length - a.text.length);
  if (!cands.length) throw new Error('No usable quote for theme: ' + t.name);
  used.add(cands[0].id);
  return { id: cands[0].id, quote: cands[0].text, score: cands[0].score, theme: t.name };
});

// 3. Fee issue: count supporting reviews in the data
const FEE = {
  exit_load: /exit load/i,
  brokerage_and_stock_charges: /brokerage|brokrage|brokerge|broker charge|charges?\b|\bfees?\b|commission|hidden|square.?off|ddpi|\bstt\b|stamp/i,
  expense_ratio_and_commission: /expense|expens|commission|regular plan|direct plan/i
};
const PRAISE = /no (other )?hidden|low (cost|charges|platform)|nominal|zero brokerage|does not charge|free of cost|minimum brokerage|charges (are )?(ok|fine|low)/i;
const HIDDEN = /hidden|without (telling|informing|notice)|bina (btaye|bataye)|pta bhi nhi|not transparent|doesn.t mention|unnecessar|deduct|extra charge|unexpected/i;
const cat = agent.fee_category;
if (!FEE[cat]) throw new Error('No fee issue chosen by the agent (category: ' + cat + ').');
const feeReviews = reviews.filter(r => FEE[cat].test(r.text) && !PRAISE.test(r.text));
if (feeReviews.length < 10) throw new Error('Fee issue "' + cat + '" appears in only ' + feeReviews.length + ' reviews; not recurring enough.');
const hiddenCount = feeReviews.filter(r => HIDDEN.test(r.text)).length;

return [{ json: {
  today: new Date().toISOString().slice(0, 10),
  n: N,
  weeks: prep.weeks,
  labelled: labelled.size,
  themes: ranked.map(t => ({ name: t.name, count: t.ids.length })),
  top: top.map(t => ({ name: t.name, count: t.ids.length })),
  quotes,
  fee_category: cat,
  fee_count: feeReviews.length,
  fee_hidden_count: hiddenCount
} }];

const KB = {
  sources: [
    { title: 'Groww: Brokerage charges and pricing', url: 'https://groww.in/pricing' },
    { title: 'Groww: Brokerage calculator', url: 'https://groww.in/calculators/brokerage-calculator' }
  ],
  categories: {
    brokerage_and_stock_charges: {
      label: 'Brokerage and other charges on stock trades',
      bullets: [
        'Equity brokerage is ₹20 or 0.1% of the order value per executed order, whichever is lower, with a minimum of ₹5.',
        'Each trade also carries regulatory and statutory charges: STT, stamp duty, exchange transaction charge, SEBI turnover charge and Investor Protection Fund Trust charge. For equity delivery, STT is 0.1% on buy and sell and stamp duty is 0.015% on buy; for equity intraday, STT is 0.025% on sell and stamp duty is 0.003% on buy.',
        'DP charges apply per sell transaction on equity delivery (depository ₹3.5, or ₹3.25 for women, plus Groww ₹16.5; ₹0 where the debit value is under ₹100). DP charges are ₹0 for intraday.',
        'An 18% GST applies on brokerage, DP charges, exchange transaction charges, IPFT, SEBI turnover charges, delayed payment charges, DDPI charges, KYC modification charges, API charges and auto square-off charges.',
        'Some charges apply only in specific cases: auto square-off of open intraday positions is ₹50 per position, delayed payment charges are 0.05% per day, and DDPI activation is ₹100 plus GST.',
        'Account opening and account maintenance are ₹0. The brokerage calculator estimates the total charges for a trade before it is placed.'
      ]
    }
  }
};

const v = $input.first().json;
const cat = KB.categories[v.fee_category];
if (!cat) throw new Error('No verified facts for fee category "' + v.fee_category + '". Add it to the KB or pick another category.');

const explainer = {
  title: cat.label,
  bullets: cat.bullets.slice(0, 6),
  links: KB.sources.slice(0, 2).map(s => s.url),
  lastChecked: v.today
};
const explainerText = [
  cat.label,
  ...explainer.bullets.map(b => '- ' + b),
  '',
  'Sources: ' + explainer.links.join(' | '),
  'Last checked: ' + explainer.lastChecked
].join('\n');

return [{ json: { ...v, fee_label: cat.label, explainer, explainerText } }];

const v = $('Fee Explainer').first().json;
const pulse = String($input.first().json.text || '').trim();
const wc = s => (s.match(/\S+/g) || []).length;

// Checks: stop here if the pulse breaks the brief
const errs = [];
if (!pulse) errs.push('pulse is empty');
if (wc(pulse) > 250) errs.push('pulse is ' + wc(pulse) + ' words (max 250)');
const missing = v.quotes.filter(q => !pulse.includes(q.quote));
if (missing.length) errs.push('quotes missing or reworded: ' + missing.map(q => q.quote.slice(0, 30)).join(' | '));
const idx = pulse.toLowerCase().lastIndexOf('action ideas');
const tail = idx >= 0 ? pulse.slice(idx) : '';
if ((tail.match(/^\s*[1-3][.)]\s/gm) || []).length < 3) errs.push('fewer than 3 numbered action ideas');
if (errs.length) throw new Error(errs.join('; '));

const e = v.explainer;
const entry = {
  date: v.today,
  top_themes: v.top.map(t => t.name),
  weekly_pulse: pulse,
  identified_fee_issue: v.fee_label,
  explanation_bullets: e.bullets,
  source_links: e.links
};

const subject = `Weekly Product Pulse + Customer Clarification — ${v.today}`;

const emailBody =
  `${pulse}\n\n----\nSupport snippet (reusable)\n\n${v.explainerText}\n`;

const docText =
  `\n\n=== ${v.today} ===\n` +
  `date: ${entry.date}\n` +
  `top_themes: ${entry.top_themes.join('; ')}\n` +
  `identified_fee_issue: ${entry.identified_fee_issue}\n\n` +
  `weekly_pulse:\n${pulse}\n\n` +
  `explanation_bullets:\n${e.bullets.map(b => '- ' + b).join('\n')}\n\n` +
  `source_links:\n${e.links.join('\n')}\n` +
  `Last checked: ${e.lastChecked}\n`;

const preview =
  `WEEKLY PULSE (${wc(pulse)} words)\n\n${pulse}\n\n` +
  `FEE EXPLAINER\n\n${v.explainerText}\n\n` +
  `If you approve: (1) this entry is appended to the Google Doc, ` +
  `(2) an email draft is created with the subject "${subject}". Nothing is sent.`;

return [{ json: { entry, subject, emailBody, docText, preview, pulseWords: wc(pulse) } }];

const prep = $('Prepare Reviews').first().json;
const agent = $('AI Agent').first().json.output;
const themes = (agent.themes || []).slice(0, 5);
if (themes.length < 3) throw new Error('Agent returned fewer than 3 themes.');

const themeList = themes.map((t, i) => `${i + 1}. ${t.name}: ${t.description || ''}`).join('\n');
const SIZE = 50;
const items = [];
for (let i = 0; i < prep.reviews.length; i += SIZE) {
  const chunk = prep.reviews.slice(i, i + SIZE);
  const batchText = chunk.map(r => `[${r.id}] ${r.text}`).join('\n');
  const chatInput =
    `Themes:\n${themeList}\n0. None of the above (praise, noise, or a topic not listed)\n\n` +
    `For each review below, choose the single best-matching theme number, or 0 if none fit.\n` +
    `If a review fits two themes, choose the one it complains about most.\n\n` +
    `Reply with ONLY one line per review, in the format: id,theme\n` +
    `Example:\n12,3\n13,0\n14,1\n` +
    `Include every review id, in order. No other text, no headings, no explanations.\n\n` +
    `Reviews:\n${batchText}`;
  items.push({ json: { chatInput, expected: chunk.length } });
}
return items;
